{"code": "import pandas as pd
import numpy as np

df_order = pd.read_excel('DuLieuBanHang.xlsx', sheet_name='DanhSachHoaDon')
df_line = pd.read_excel('DanhSachHoaDonChiTiet.xlsx', sheet_name='Sheet1')

# Robust date parse for 'Thời gian': numeric -> excel serial, else string dd/mm/yyyy
s = df_order['Thời gian'].astype(str).str.strip()
def parse_date(v):
    v = str(v).strip()
    try:
        return pd.to_datetime(v, format='%Y%m%d')
    except:
        pass
    try:
        return pd.to_datetime(v, format='%d/%m/%Y')
    except:
        pass
    try:
        return pd.to_datetime(v, format='%m/%d/%Y')
    except:
        pass
    try:
        return pd.to_datetime(v, format='%Y-%m-%d')
    except:
        pass
    # excel serial
    try:
        return pd.to_datetime(int(float(v)), format='excel')
    except:
        return pd.NaT

df_order['date'] = s.apply(parse_date)
print("April 2025 parsed dates sample:")
apr = df_order[(df_order['date']>=pd.Timestamp('2025-04-01'))&(df_order['date']<=pd.Timestamp('2025-04-30'))]
print(apr['date'].dtype)
print(apr['date'].min(), apr['date'].max())

# Normalize status
status_map = {
    'hủy đơn':'hủy', 'Đã huỷ':'hủy',
    'trả hàng':'trả', 'Đã trả hàng':'trả',
}
df_order['status_norm'] = df_order['Trạng thái'].astype(str).str.strip().str.lower().replace(status_map)
print("\nStatus normalized:")
print(df_order['status_norm'].value_counts(dropna=False))

# Revenue per day = sum of Thành tiền from line items, excluding hủy & trả
df_line['amount'] = df_line['Thành tiền'].astype(str).str.replace(',', '').astype(float)
df_line = df_line.copy()
df_line['order_date'] = df_line['Mã hóa đơn'].map(df_order.set_index('Mã hóa đơn')['date'])
df_line['status'] = df_line['Mã hóa đơn'].map(df_order.set_index('Mã hóa đơn')['status_norm'])

valid = df_line[df_line['status'].isin(['đã lấy','hoàn thành','đang xử lý'])]
print("\nValid line rows:", len(valid), "total line rows:", len(df_line))

rev = valid.groupby('order_date')['amount'].sum()
apr_rev = rev[(rev.index>=pd.Timestamp('2025-04-01'))&(rev.index<=pd.Timestamp('2025-04-30'))]
top = apr_rev.sort_values(ascending=False).head(5)
print("\nTop 5 days in April 2025 by revenue:")
for d,v in top.items():
    print(d.date(), vn_num(v) if False else v)
print("\nTotal April revenue:", apr_rev.sum())
"}

